PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS objects(id INTEGER PRIMARY KEY, sha256 TEXT NOT NULL UNIQUE, verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sources(id INTEGER PRIMARY KEY, source_id TEXT NOT NULL UNIQUE, discovered INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS bindings(source INTEGER NOT NULL REFERENCES sources(id), object INTEGER NOT NULL REFERENCES objects(id), PRIMARY KEY(source,object)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS binding_object ON bindings(object,source);
CREATE TABLE IF NOT EXISTS recipes(id TEXT PRIMARY KEY, json TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS versions(recipe TEXT PRIMARY KEY REFERENCES recipes(id), version INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS runs(ordinal INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, status TEXT NOT NULL, request TEXT NOT NULL, sources TEXT NOT NULL,
  planned INTEGER NOT NULL DEFAULT 0, completed INTEGER NOT NULL DEFAULT 0, reused INTEGER NOT NULL DEFAULT 0, failed INTEGER NOT NULL DEFAULT 0, bytes_read INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE TABLE IF NOT EXISTS plan(run TEXT NOT NULL REFERENCES runs(id), object INTEGER NOT NULL REFERENCES objects(id), source INTEGER NOT NULL REFERENCES sources(id),
  pack TEXT NOT NULL, offset INTEGER NOT NULL, length INTEGER NOT NULL, state INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(run,object)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS physical_plan ON plan(run,state,source,pack,offset,object);
CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY, run TEXT NOT NULL REFERENCES runs(id), state TEXT NOT NULL, request TEXT NOT NULL, receipt TEXT) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS pending_batches ON batches(run,state);
CREATE UNIQUE INDEX IF NOT EXISTS single_pending_batch ON batches((1)) WHERE state='pending';
CREATE TABLE IF NOT EXISTS outcomes(object INTEGER NOT NULL REFERENCES objects(id), recipe TEXT NOT NULL, status TEXT NOT NULL, batch TEXT NOT NULL, error TEXT, PRIMARY KEY(object,recipe)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS outcomes_recipe ON outcomes(recipe,status,object);
CREATE TABLE IF NOT EXISTS coverage_counts(source INTEGER NOT NULL REFERENCES sources(id),recipe TEXT NOT NULL,succeeded INTEGER NOT NULL DEFAULT 0,failed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(source,recipe)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS projection_pending(recipe TEXT NOT NULL,object INTEGER NOT NULL,PRIMARY KEY(recipe,object)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS projection_pending_object ON projection_pending(object,recipe);
CREATE TABLE IF NOT EXISTS run_failures(run TEXT NOT NULL REFERENCES runs(id),object INTEGER NOT NULL,recipe TEXT NOT NULL,error TEXT,PRIMARY KEY(run,object,recipe)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS hashes(object INTEGER PRIMARY KEY REFERENCES objects(id), value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hash_bands(band INTEGER NOT NULL, bits INTEGER NOT NULL, object INTEGER NOT NULL REFERENCES objects(id), PRIMARY KEY(band,bits,object)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS run_scopes(run TEXT PRIMARY KEY REFERENCES runs(id), member_run TEXT NOT NULL REFERENCES runs(id), ready INTEGER NOT NULL DEFAULT 0) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS members(scope TEXT NOT NULL REFERENCES runs(id),source INTEGER NOT NULL REFERENCES sources(id),row_id INTEGER NOT NULL,object INTEGER NOT NULL REFERENCES objects(id),pack TEXT NOT NULL,offset INTEGER NOT NULL,length INTEGER NOT NULL,PRIMARY KEY(scope,source,row_id)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS member_objects ON members(scope,object,source);
CREATE TABLE IF NOT EXISTS run_metrics(run TEXT PRIMARY KEY REFERENCES runs(id),json TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS snapshots(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),versions TEXT NOT NULL) WITHOUT ROWID;
PRAGMA user_version=2;
